def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_coop = sum(1 for a in opp if a == 'C')
    opp_coop_rate = opp_coop / n
    last_me, last_opp = history[-1]

    retaliate = 0
    forgive = 0
    for i in range(n - 1):
        if my[i] == 'D' and opp[i] == 'C':
            if opp[i + 1] == 'D':
                retaliate += 1
            elif opp[i + 1] == 'C':
                forgive += 1

    if forgive >= 2 and retaliate == 0 and opp_coop_rate > 0.8:
        if last_opp == 'D':
            return 'C'
        return 'D'

    if retaliate >= 1:
        if last_opp == 'D' and last_me == 'C':
            if opp_coop_rate > 0.7 and n > 5:
                return 'C'
            return 'D'
        if last_opp == 'C' and last_me == 'D':
            return 'C'
        if opp_coop_rate > 0.85:
            return 'C'
        if opp_coop_rate < 0.3:
            return 'D'
        if n >= 10:
            recent = opp[-10:]
            recent_rate = sum(1 for a in recent if a == 'C') / len(recent)
            if recent_rate < opp_coop_rate - 0.3:
                return 'D'
            if recent_rate > opp_coop_rate + 0.3:
                return 'C'
        if n > 80:
            if opp_coop_rate < 0.5:
                return 'D'
            return 'C'
        if last_opp == 'D':
            if rng.random() < 0.1 and opp_coop_rate > 0.5:
                return 'C'
            return 'D'
        return 'C'

    if 'D' not in my and n >= 5 and opp_coop_rate > 0.9:
        if all(my[i] == 'C' and opp[i] == 'C' for i in range(n - 5, n)):
            return 'D'

    if forgive == 1 and retaliate == 0 and last_me == 'C' and last_opp == 'C' and opp_coop_rate > 0.8:
        return 'D'

    if last_opp == 'D' and last_me == 'C':
        if opp_coop_rate > 0.7 and n > 5:
            return 'C'
        return 'D'
    if last_opp == 'C' and last_me == 'D':
        return 'C'
    if opp_coop_rate > 0.85:
        return 'C'
    if opp_coop_rate < 0.3:
        return 'D'
    if n >= 10:
        recent = opp[-10:]
        recent_rate = sum(1 for a in recent if a == 'C') / len(recent)
        if recent_rate < opp_coop_rate - 0.3:
            return 'D'
        if recent_rate > opp_coop_rate + 0.3:
            return 'C'
    if n > 80:
        if opp_coop_rate < 0.5:
            return 'D'
        return 'C'
    if last_opp == 'D':
        if rng.random() < 0.1 and opp_coop_rate > 0.5:
            return 'C'
        return 'D'
    return 'C'
